window.HOEREN_TESTS[23] = {"id":"kinder-und-erziehung","name":"Kinder und Erziehung","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Eltern, der Kindergarten Sonnenschein hat ab nächster Woche neue Öffnungszeiten. Statt 7 bis 16 Uhr sind wir nun von 7 Uhr 30 bis 17 Uhr offen. Nicht den ganzen Tag, nur bis 17 Uhr. Mehr Zeit am Nachmittag, also. Aber wir öffnen 30 Minuten später am Morgen. Bitte planen Sie das in Ihren Alltag ein. Danke!","gender":"f","q":"Wie sind die neuen Öffnungszeiten?","opts":["7 bis 16 Uhr wie früher.","Den ganzen Tag.","7 Uhr 30 bis 17 Uhr."],"correct":2},{"transcript":"Hallo Frau Schmidt, hier ist die Schule. Ihr Sohn Tim hat heute in der Pause einen kleinen Sturz auf dem Spielplatz gehabt. Er hat sich am Knie gestoßen, ist aber wieder okay. Wir haben ein Pflaster gegeben. Sie müssen nicht extra abholen, aber kontrollieren Sie das Knie heute Abend.","gender":"f","q":"Was ist mit Tim passiert?","opts":["Er ist krank.","Er hat sich verlaufen.","Er hatte einen kleinen Sturz."],"correct":2},{"transcript":"Hi Schatz, hier ist Mama. Also, wegen Linas Geburtstagsparty am Samstag — wir haben jetzt 12 Kinder eingeladen, statt 8 wie geplant. Lina möchte ihre ganze Klasse einladen. Das wird viel Arbeit, also helfe ich beim Kuchenbacken? Auch Pizza haben wir bestellt, das ist einfacher als zu kochen.","gender":"f","q":"Wie viele Kinder kommen zur Party?","opts":["12 Kinder.","Die ganze Klasse — 25 Kinder.","8 Kinder."],"correct":0},{"transcript":"Achtung an alle Eltern: Am Donnerstag fällt der Schulunterricht aus, wegen Lehrerkonferenz. Die Kinder kommen erst am Freitag wieder. Wenn Sie keine Kinderbetreuung haben, bietet die Schule eine Notfall-Betreuung an — von 8 bis 13 Uhr. Die Notfall-Betreuung ist also da. Bitte melden Sie sich vorab im Sekretariat an. Danke!","gender":"m","q":"Was bietet die Schule am Donnerstag?","opts":["Eine Notfall-Betreuung.","Normalen Unterricht.","Gar nichts."],"correct":0},{"transcript":"Hallo Tom, hier ist Sara. Mein Sohn Lukas möchte mit deinem Sohn am Wochenende Fußball spielen. Nicht Spielzeug tauschen und keine Hausaufgaben, wirklich Fußball spielen! Können sie sich bei uns treffen, am Samstagnachmittag um 14 Uhr? Wir haben ja einen Garten. Lukas freut sich schon. Wenn das nicht klappt, finden wir einen anderen Termin. Danke!","gender":"f","q":"Was möchten die Kinder zusammen machen?","opts":["Spielzeug tauschen.","Fußball spielen.","Hausaufgaben machen."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Welches Training ist an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Der Stundenplan von Mia ist für diese Woche offen. Ich habe den Kalender."},{"speaker":"Lukas","gender":"m","text":"Dann füllen wir die fünf Tage. Sie soll nicht jeden Nachmittag dasselbe machen."},{"speaker":"Lisa","gender":"f","text":"Sie spielt montags Fußball im Verein. Das Training ist auf dem großen Platz."},{"speaker":"Lukas","gender":"m","text":"Fußball im Verein hält sie fit. Wollte sie nicht Klavier lernen?"},{"speaker":"Lisa","gender":"f","text":"Nein. Klavier lernt sie diese Woche nicht. Das Instrument bleibt im Schrank."},{"speaker":"Lukas","gender":"m","text":"Die Tanzschuhe zieht sie am Dienstag an."},{"speaker":"Lisa","gender":"f","text":"Sie tanzt dann Ballett. Die Stunde in der Schule beginnt um vier."},{"speaker":"Lukas","gender":"m","text":"Das mag sie schon seit Jahren. Die Probe am Mittwoch ist mit Musik gefüllt."},{"speaker":"Lisa","gender":"f","text":"Sie singt im Kinderchor. Die Probe findet in der Aula statt."},{"speaker":"Lukas","gender":"m","text":"Der Kinderchor trifft sich nur an diesem Tag. Steht Reiten auf dem Hof auch noch im Plan?"},{"speaker":"Lisa","gender":"f","text":"Reiten gehen wir nicht. Das Pferd ist diese Woche bei der Tierärztin."},{"speaker":"Lukas","gender":"m","text":"Bei Mia wird es am Donnerstag sportlicher."},{"speaker":"Lisa","gender":"f","text":"Sie macht Karate. Der neue Gürtel hängt schon an ihrer Tür."},{"speaker":"Lukas","gender":"m","text":"Karate gibt ihr jedes Mal Mut. Sie soll am Freitag ruhiger werden."},{"speaker":"Lisa","gender":"f","text":"Sie spielt Schach in der Bibliothek. Sie denkt dort gern ruhig nach."},{"speaker":"Lukas","gender":"m","text":"Einverstanden. Ich hänge den Plan an den Kühlschrank."}],"options":[{"letter":"a","text":"lernt Klavier"},{"letter":"b","text":"geht reiten"},{"letter":"c","text":"tanzt Ballett"},{"letter":"d","text":"macht Karate"},{"letter":"e","text":"lernt Sprachen"},{"letter":"f","text":"spielt Fußball im Verein"},{"letter":"g","text":"malt und zeichnet"},{"letter":"h","text":"spielt Schach"},{"letter":"i","text":"singt im Kinderchor"}],"items":[{"person":"Montag","correct":"f"},{"person":"Dienstag","correct":"c"},{"person":"Mittwoch","correct":"i"},{"person":"Donnerstag","correct":"d"},{"person":"Freitag","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mutter","gender":"f","text":"Welche Schule für unsere Tochter — die A oder die B? Oder sollen wir beide anschauen und später wählen?"},{"speaker":"Vater","gender":"m","text":"Die A ist näher, aber B hat besseren Ruf. Beide gleichzeitig geht nicht."},{"speaker":"Mutter","gender":"f","text":"Für ein 6-jähriges Mädchen ist eine nahe Schule wichtiger als der Ruf. Schule B ist weit."},{"speaker":"Vater","gender":"m","text":"Stimmt, dann Schule A. Nicht B, und nicht beide."},{"speaker":"Mutter","gender":"f","text":"Gut, ich rufe Schule A morgen an und frage nach einem Platz."}],"q":"Welche Schule wird gewählt?","opts":["Schule B.","Schule A.","Beide."],"correct":1},{"lines":[{"speaker":"Tochter","gender":"f","text":"Mama, kann ich heute zum Freund? Sofort nach der Schule, bitte."},{"speaker":"Mutter","gender":"f","text":"Hast du Hausaufgaben gemacht? Englisch und der Rest? Schlafen musst du noch nicht."},{"speaker":"Tochter","gender":"f","text":"Mathe ja. Englisch noch nicht. Deshalb wollte ich sofort zum Freund."},{"speaker":"Mutter","gender":"f","text":"Englisch erst zu Ende, dann zum Freund. Nicht sofort und nicht ins Bett."},{"speaker":"Tochter","gender":"f","text":"Okay, ich mache Englisch fertig. Danach darf ich gehen, ja?"}],"q":"Was soll die Tochter zuerst machen?","opts":["Sofort zum Freund.","Schlafen.","Englisch fertig machen."],"correct":2},{"lines":[{"speaker":"Sohn","gender":"m","text":"Papa, ich will einen Hund. Bitte, wirklich, nicht gar kein Tier."},{"speaker":"Vater","gender":"m","text":"Hund braucht viel Pflege. Bist du bereit? Eine Katze wäre einfacher."},{"speaker":"Sohn","gender":"m","text":"Ja! Ich gehe jeden Tag spazieren mit ihm. Gar kein Tier will ich nicht."},{"speaker":"Vater","gender":"m","text":"Lass uns erst eine Katze probieren. Wenn das gut läuft, dann Hund. Nicht sofort den Hund."},{"speaker":"Sohn","gender":"m","text":"Okay, eine Katze ist auch gut. Dann lerne ich zuerst die Pflege."}],"q":"Welches Tier bekommt der Sohn zuerst?","opts":["Einen Hund.","Eine Katze.","Gar kein Tier."],"correct":1},{"lines":[{"speaker":"Lehrerin","gender":"f","text":"Frau Schmidt, Tim macht große Fortschritte in Mathe. Das wollte ich Ihnen sagen."},{"speaker":"Mutter","gender":"f","text":"Wirklich? Das freut mich. Hat er sich verändert, oder bleibt alles gleich?"},{"speaker":"Lehrerin","gender":"f","text":"Vor einem Jahr war er der schlechteste. Heute einer der besten. Sehr stolze Entwicklung, nicht schlechter geworden."},{"speaker":"Mutter","gender":"f","text":"Toll! Vielen Dank für Ihre Hilfe. Vom schlechtesten zum besten — das ist viel Arbeit."},{"speaker":"Lehrerin","gender":"f","text":"Gerne, er übt zu Hause, das merkt man. Weiter so."}],"q":"Wie hat sich Tim entwickelt?","opts":["Vom schlechtesten zum besten.","Vom besten zum schlechtesten.","Hat sich nicht verändert."],"correct":0},{"lines":[{"speaker":"Mutter","gender":"f","text":"Was möchtest du zum Geburtstag? Skateboard, Fahrrad, oder dein altes Rad reicht?"},{"speaker":"Sohn","gender":"m","text":"Ein Skateboard wäre super. Oder ein neues Fahrrad, das alte ist zu klein."},{"speaker":"Mutter","gender":"f","text":"Hmm, Skateboard ist zu gefährlich für 8-jährige. Das alte Fahrrad ist wirklich klein."},{"speaker":"Sohn","gender":"m","text":"Dann ein neues Fahrrad? Ich habe ein altes, aber das ist zu klein, das will ich nicht behalten."},{"speaker":"Mutter","gender":"f","text":"Fahrrad ist gut. Ich kaufe ein neues, kein Skateboard."}],"q":"Was bekommt der Sohn?","opts":["Ein neues Fahrrad.","Skateboard.","Sein altes Fahrrad."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Becker, einer Kindergärtnerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Becker, Sie sind Kindergärtnerin seit 22 Jahren. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Becker","gender":"f","text":"Schon als 15-jährige habe ich gewusst — Kinder sind meine Welt. Meine eigene Mutter war auch Kindergärtnerin, aber das war Zufall. Ich habe diesen Beruf selbst gewählt, nicht weil meine Mutter ihn hatte."},{"speaker":"Reporter","gender":"m","text":"Wie hat sich der Beruf in 22 Jahren verändert?"},{"speaker":"Becker","gender":"f","text":"Sehr. Heute haben wir mehr Kinder mit verschiedenen Sprachen — vor 22 Jahren sprachen alle Deutsch zu Hause. Jetzt habe ich Kinder, die zu Hause Türkisch, Russisch, Arabisch oder andere Sprachen sprechen. Das ist eine Bereicherung, aber auch Herausforderung."},{"speaker":"Reporter","gender":"m","text":"Was lieben Sie am Beruf?"},{"speaker":"Becker","gender":"f","text":"Die ehrliche Freude der Kinder. Wenn ein Kind etwas Neues lernt — wenn ein 3-Jähriger plötzlich seinen Namen schreiben kann — das ist ein magischer Moment. So pur und unbefangen."},{"speaker":"Reporter","gender":"m","text":"Und das Schwierigste?"},{"speaker":"Becker","gender":"f","text":"Schwierige Eltern, nicht Kinder. Manche Eltern haben unrealistische Erwartungen oder mischen sich in alles ein. Da muss ich diplomatisch sein. Aber Kinder selbst sind selten schwierig — sie sind nur Kinder."},{"speaker":"Reporter","gender":"m","text":"Haben Sie selbst Kinder?"},{"speaker":"Becker","gender":"f","text":"Drei. Zwei sind schon erwachsen, einer noch in der Schule. Mein jüngster ist 13. Ich habe also tagsüber Kindergartenkinder und abends einen Teenager — alle Altersgruppen!"}],"items":[{"q":"Frau Becker ist Kindergärtnerin geworden, weil ihre Mutter es war.","correct":"nein"},{"q":"Heute sprechen Kinder im Kindergarten verschiedene Sprachen zu Hause.","correct":"ja"},{"q":"Sie findet schwierige Eltern anstrengender als schwierige Kinder.","correct":"ja"},{"q":"Sie hat keine eigenen Kinder.","correct":"nein"},{"q":"Ihr jüngster Sohn ist auch noch im Kindergarten.","correct":"nein"}]}]};
